691: /// Chrome versions. This order avoids triggering duplicate remote-debugging
692: /// permission prompts (#1210, #1206).
693: async fn resolve_cdp_from_active_port(port: u16, ws_path: &str) -> Result<String, String> {
694:     let ws_url = format!("ws://127.0.0.1:{}{}", port, ws_path);
695:     if verify_ws_endpoint(&ws_url).await {
