710: /// Verify that a WebSocket endpoint is a live CDP server by sending
711: /// `Browser.getVersion` and checking for a valid response.
712: async fn verify_ws_endpoint(ws_url: &str) -> bool {
713:     use futures_util::{SinkExt, StreamExt};
714:     use tokio_tungstenite::tungstenite::Message;
715: 
716:     let timeout = Duration::from_secs(2);
717:     let result = tokio::time::timeout(timeout, async {
718:         let (mut ws, _) = tokio_tungstenite::connect_async(ws_url).await.ok()?;
719:         let cmd = r#"{"id":1,"method":"Browser.getVersion"}"#;
720:         ws.send(Message::Text(cmd.into())).await.ok()?;
721:         while let Some(Ok(msg)) = ws.next().await {
722:             if let Message::Text(text) = msg {
723:                 if let Ok(v) = serde_json::from_str::<serde_json::Value>(&text) {
724:                     if v.get("id").and_then(|id| id.as_u64()) == Some(1) {
725:                         let _ = ws.close(None).await;
726:                         return Some(());
727:                     }
728:                 }
729:             }
730:         }
731:         None
732:     })
733:     .await;
734:     matches!(result, Ok(Some(())))
735: }
