25: // Update Cargo.toml
26: const cargoTomlPath = join(cliDir, "Cargo.toml");
27: let cargoToml = readFileSync(cargoTomlPath, "utf-8");
28: const cargoVersionRegex = /^version\s*=\s*"[^"]*"/m;
29: const newCargoVersion = `version = "${version}"`;
30: 
31: let cargoTomlUpdated = false;
32: if (cargoVersionRegex.test(cargoToml)) {
33:   const oldMatch = cargoToml.match(cargoVersionRegex)?.[0];
34:   if (oldMatch !== newCargoVersion) {
35:     cargoToml = cargoToml.replace(cargoVersionRegex, newCargoVersion);
36:     writeFileSync(cargoTomlPath, cargoToml);
37:     console.log(`  Updated cli/Cargo.toml: ${oldMatch} -> ${newCargoVersion}`);
38:     cargoTomlUpdated = true;
39:   } else {
40:     console.log(`  cli/Cargo.toml already up to date`);
41:   }
42: } else {
43:   console.error("  Could not find version field in cli/Cargo.toml");
44:   process.exit(1);
