60: const sandboxPkgPath = join(rootDir, "packages", "@agent-browser", "sandbox", "package.json");
61: const sandboxPkg = JSON.parse(readFileSync(sandboxPkgPath, "utf-8"));
62: if (sandboxPkg.version !== version) {
63:   const oldVersion = sandboxPkg.version;
64:   sandboxPkg.version = version;
65:   writeFileSync(sandboxPkgPath, JSON.stringify(sandboxPkg, null, 2) + "\n");
66:   console.log(`  Updated packages/@agent-browser/sandbox/package.json: ${oldVersion} -> ${version}`);
67: } else {
68:   console.log(`  packages/@agent-browser/sandbox/package.json already up to date`);
69: }
